import json

# Parse TSL specification
with open('/workdir/data/input_tsl.txt', 'r') as f:
    content = f.read()

lines = content.strip().split('\n')
current_category = None
current_subcategory = None
structure = {}

for line in lines:
    line = line.strip()
    if not line:
        continue

    if line.startswith('Parameters:') or line.startswith('Environments:'):
        current_category = line.split(':')[0].strip()
        structure[current_category] = {}
        current_subcategory = None
    elif current_category is not None and line.startswith('    '):
        # Check if it's a subcategory (has colon)
        if ':' in line:
            parts = line.split(':')
            subcat_name = parts[0].strip()
            structure[current_category][subcat_name] = []
            current_subcategory = subcat_name
        else:
            # It's a choice
            choice_name = line.split('[')[0].strip()
            annotations = []
            if '[' in line:
                ann_part = line.split('[')[1]
                ann_part = ann_part.split(']')[0]
                if ann_part:
                    annotations = ann_part.split()

            if current_subcategory is not None:
                structure[current_category][current_subcategory].append({
                    'name': choice_name,
                    'annotations': annotations
                })

# Debug: print each line and what it represents
print("Line-by-line analysis:")
for i, line in enumerate(lines):
    stripped = line.strip()
    print(f"  Line {i+1}: '{stripped}' -> category: {current_category}, subcat: {current_subcategory}")

print("\nFinal structure:")
print(json.dumps(structure, indent=2))
